CREATE TABLE `subject_attempts` (
	`id` text PRIMARY KEY NOT NULL,
	`student_id` text NOT NULL,
	`set_id` text NOT NULL,
	`answers` text NOT NULL,
	`score` integer NOT NULL,
	`total` integer NOT NULL,
	`submitted_at` integer NOT NULL,
	FOREIGN KEY (`student_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`set_id`) REFERENCES `subject_question_sets`(`id`) ON UPDATE no action ON DELETE no action
);
--> statement-breakpoint
CREATE UNIQUE INDEX `subject_attempt_once` ON `subject_attempts` (`student_id`,`set_id`);--> statement-breakpoint
CREATE TABLE `subject_purchases` (
	`id` text PRIMARY KEY NOT NULL,
	`student_id` text NOT NULL,
	`teacher_id` text NOT NULL,
	`class_level` text NOT NULL,
	`subject` text NOT NULL,
	`product` text NOT NULL,
	`amount` integer NOT NULL,
	`receipt` text NOT NULL,
	`phone` text NOT NULL,
	`status` text DEFAULT 'pending' NOT NULL,
	`created_at` integer NOT NULL,
	`reviewed_at` integer,
	`reviewed_by` text,
	`note` text DEFAULT '' NOT NULL,
	`expires_at` integer,
	FOREIGN KEY (`student_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`teacher_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`reviewed_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
--> statement-breakpoint
CREATE UNIQUE INDEX `subject_purchase_receipt` ON `subject_purchases` (`receipt`);--> statement-breakpoint
CREATE UNIQUE INDEX `subject_purchase_pending` ON `subject_purchases` (`student_id`,`teacher_id`,`class_level`,`subject`,`product`) WHERE status='pending';--> statement-breakpoint
CREATE INDEX `subject_purchase_access` ON `subject_purchases` (`student_id`,`teacher_id`,`class_level`,`subject`,`product`,`status`,`expires_at`);--> statement-breakpoint
CREATE TABLE `subject_question_sets` (
	`id` text PRIMARY KEY NOT NULL,
	`teacher_id` text,
	`lesson_id` text,
	`source_key` text NOT NULL,
	`class_level` text NOT NULL,
	`subject` text NOT NULL,
	`title` text NOT NULL,
	`questions` text NOT NULL,
	`status` text DEFAULT 'draft' NOT NULL,
	`created_at` integer NOT NULL,
	`reviewed_by` text,
	`reviewed_at` integer,
	FOREIGN KEY (`teacher_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`lesson_id`) REFERENCES `lessons`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`reviewed_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
--> statement-breakpoint
CREATE UNIQUE INDEX `subject_questions_source` ON `subject_question_sets` (`source_key`,`class_level`);--> statement-breakpoint
CREATE INDEX `subject_questions_course` ON `subject_question_sets` (`teacher_id`,`class_level`,`subject`,`status`);--> statement-breakpoint
CREATE TABLE `subject_tutorials` (
	`id` text PRIMARY KEY NOT NULL,
	`teacher_id` text NOT NULL,
	`video_id` text NOT NULL,
	`class_level` text NOT NULL,
	`subject` text NOT NULL,
	`title` text NOT NULL,
	`description` text NOT NULL,
	`status` text DEFAULT 'published' NOT NULL,
	`created_at` integer NOT NULL,
	FOREIGN KEY (`teacher_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`video_id`) REFERENCES `learning_videos`(`id`) ON UPDATE no action ON DELETE no action
