CREATE UNIQUE INDEX `subject_tutorial_course` ON `subject_tutorials` (`video_id`,`class_level`,`subject`);--> statement-breakpoint
CREATE INDEX `subject_tutorial_listing` ON `subject_tutorials` (`teacher_id`,`class_level`,`subject`,`status`);
