INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('c2a03284-335e-4723-a8b0-f87f93619317','revision:revision-01','grade-7','mathematics','Fractions · Revision notes','[{"text":"Complete the statement from your lesson notes: Adding fractions with different denominators first requires a common ____.","choices":["denominator","whole","considered","fraction"],"correct":0,"explanation":"Adding fractions with different denominators first requires a common denominator."},{"text":"Complete the statement from your lesson notes: The parts must refer to the same sized ____.","choices":["denominator","whole","considered","fraction"],"correct":1,"explanation":"The parts must refer to the same sized whole."},{"text":"Complete the statement from your lesson notes: The numerator counts how many of those parts are being ____.","choices":["denominator","whole","considered","fraction"],"correct":2,"explanation":"The numerator counts how many of those parts are being considered."},{"text":"Complete the statement from your lesson notes: Multiplying numerator and denominator by the same non-zero number creates an equivalent ____.","choices":["denominator","whole","considered","fraction"],"correct":3,"explanation":"Multiplying numerator and denominator by the same non-zero number creates an equivalent fraction."},{"text":"Complete the statement from your lesson notes: Simplifying a fraction removes a common factor without changing its ____.","choices":["value","denominator","whole","considered"],"correct":0,"explanation":"Simplifying a fraction removes a common factor without changing its value."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('62fc0841-5632-4833-a36e-ef69c2c0b7b7','revision:revision-02','grade-7','general','Mixtures · Revision notes','[{"text":"Complete the statement from your lesson notes: A mixture contains substances combined without all of them forming a new chemical ____.","choices":["substance","filtration","filtrate","residue"],"correct":0,"explanation":"A mixture contains substances combined without all of them forming a new chemical substance."},{"text":"Complete the statement from your lesson notes: An insoluble solid can be separated from a liquid by ____.","choices":["substance","filtration","filtrate","residue"],"correct":1,"explanation":"An insoluble solid can be separated from a liquid by filtration."},{"text":"Complete the statement from your lesson notes: Particles that pass through a filter remain in the collected ____.","choices":["substance","filtration","filtrate","residue"],"correct":2,"explanation":"Particles that pass through a filter remain in the collected filtrate."},{"text":"Complete the statement from your lesson notes: Filtering a mixture of sand and water leaves sand as ____.","choices":["substance","filtration","filtrate","residue"],"correct":3,"explanation":"Filtering a mixture of sand and water leaves sand as residue."},{"text":"Complete the statement from your lesson notes: Dissolved salt passes through ordinary filter paper together with the ____.","choices":["solvent","substance","filtration","filtrate"],"correct":0,"explanation":"Dissolved salt passes through ordinary filter paper together with the solvent."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('1d3b01a8-85cc-4654-afe8-87635833b8ab','revision:revision-03','grade-7','agriculture','Controlling Soil Pollution · Revision notes','[{"text":"Complete the statement from your lesson notes: Soil pollution occurs when harmful substances contaminate the soil ____.","choices":["environment","organisms","farmland","disposal"],"correct":0,"explanation":"Soil pollution occurs when harmful substances contaminate the soil environment."},{"text":"Complete the statement from your lesson notes: Poorly discarded plastics can interfere with cultivation and soil ____.","choices":["environment","organisms","farmland","disposal"],"correct":1,"explanation":"Poorly discarded plastics can interfere with cultivation and soil organisms."},{"text":"Complete the statement from your lesson notes: Uncontrolled dumping can introduce harmful substances into water and ____.","choices":["environment","organisms","farmland","disposal"],"correct":2,"explanation":"Uncontrolled dumping can introduce harmful substances into water and farmland."},{"text":"Complete the statement from your lesson notes: Sorting household waste supports safer reuse, recycling and ____.","choices":["environment","organisms","farmland","disposal"],"correct":3,"explanation":"Sorting household waste supports safer reuse, recycling and disposal."},{"text":"Complete the statement from your lesson notes: Suitable uncontaminated plant material can be managed through ____.","choices":["composting","environment","organisms","farmland"],"correct":0,"explanation":"Suitable uncontaminated plant material can be managed through composting."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('87b200bb-e8b4-4f3c-a1a7-37bbbe059e21','revision:revision-04','grade-7','english','Listening for Main Idea · Revision notes','[{"text":"Complete the statement from your lesson notes: The main idea expresses the central message of a spoken ____.","choices":["passage","message","theme","meaning"],"correct":0,"explanation":"The main idea expresses the central message of a spoken passage."},{"text":"Complete the statement from your lesson notes: A detail such as the number of seedlings supports that ____.","choices":["passage","message","theme","meaning"],"correct":1,"explanation":"A detail such as the number of seedlings supports that message."},{"text":"Complete the statement from your lesson notes: Repeated words can help a listener notice the speaker’s central ____.","choices":["passage","message","theme","meaning"],"correct":2,"explanation":"Repeated words can help a listener notice the speaker’s central theme."},{"text":"Complete the statement from your lesson notes: A title can suggest a topic but does not always express the complete ____.","choices":["passage","message","theme","meaning"],"correct":3,"explanation":"A title can suggest a topic but does not always express the complete meaning."},{"text":"Complete the statement from your lesson notes: Brief notes help the listener retain important information from the ____.","choices":["presentation","passage","message","theme"],"correct":0,"explanation":"Brief notes help the listener retain important information from the presentation."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('e7dc2ddd-614c-4b6c-adfc-c38136dc9d21','revision:revision-05','grade-8','mathematics','Rates, Ratio, Proportions and Percentages · Revision notes','[{"text":"Complete the statement from your lesson notes: A ratio compares quantities using an agreed ____.","choices":["order","factor","simplification","hundred"],"correct":0,"explanation":"A ratio compares quantities using an agreed order."},{"text":"Complete the statement from your lesson notes: Direct proportion means one quantity changes by the same ____ as another.","choices":["order","factor","simplification","hundred"],"correct":1,"explanation":"Direct proportion means one quantity changes by the same factor as another."},{"text":"Complete the statement from your lesson notes: Quantities in a ratio must use compatible units before ____.","choices":["order","factor","simplification","hundred"],"correct":2,"explanation":"Quantities in a ratio must use compatible units before simplification."},{"text":"Complete the statement from your lesson notes: A percentage describes a quantity as a fraction with denominator one ____.","choices":["order","factor","simplification","hundred"],"correct":3,"explanation":"A percentage describes a quantity as a fraction with denominator one hundred."},{"text":"Complete the statement from your lesson notes: For a mixture ratio of 2:3 with 25 parts altogether, there are 5 equal ratio ____.","choices":["units","order","factor","simplification"],"correct":0,"explanation":"For a mixture ratio of 2:3 with 25 parts altogether, there are 5 equal ratio units."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('b4146665-d279-41f0-af35-d89f8e441aaf','revision:revision-06','grade-8','general','The Cell · Revision notes','[{"text":"Complete the statement from your lesson notes: A cell is a basic structural unit of a living ____.","choices":["organism","cell","information","membrane"],"correct":0,"explanation":"A cell is a basic structural unit of a living organism."},{"text":"Complete the statement from your lesson notes: A simplified diagram does not show every feature of every ____.","choices":["organism","cell","information","membrane"],"correct":1,"explanation":"A simplified diagram does not show every feature of every cell."},{"text":"Complete the statement from your lesson notes: The nucleus of a typical eukaryotic cell contains genetic ____.","choices":["organism","cell","information","membrane"],"correct":2,"explanation":"The nucleus of a typical eukaryotic cell contains genetic information."},{"text":"Complete the statement from your lesson notes: A plant cell wall provides support outside the cell ____.","choices":["organism","cell","information","membrane"],"correct":3,"explanation":"A plant cell wall provides support outside the cell membrane."},{"text":"Complete the statement from your lesson notes: Chloroplasts in photosynthetic plant cells contain chlorophyll for absorbing ____.","choices":["light","organism","cell","information"],"correct":0,"explanation":"Chloroplasts in photosynthetic plant cells contain chlorophyll for absorbing light."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('7b89c1e4-50e9-4f2c-a243-a3d72282262f','revision:revision-07','grade-8','agriculture','Soil Conservation Measures · Revision notes','[{"text":"Complete the statement from your lesson notes: Soil erosion involves the removal and transport of soil ____.","choices":["particles","field","surface","cover"],"correct":0,"explanation":"Soil erosion involves the removal and transport of soil particles."},{"text":"Complete the statement from your lesson notes: Moving water can carry exposed particles away from a ____.","choices":["particles","field","surface","cover"],"correct":1,"explanation":"Moving water can carry exposed particles away from a field."},{"text":"Complete the statement from your lesson notes: Wind can remove dry particles from an unprotected soil ____.","choices":["particles","field","surface","cover"],"correct":2,"explanation":"Wind can remove dry particles from an unprotected soil surface."},{"text":"Complete the statement from your lesson notes: Vegetation roots help bind the soil and provide protective ____.","choices":["particles","field","surface","cover"],"correct":3,"explanation":"Vegetation roots help bind the soil and provide protective cover."},{"text":"Complete the statement from your lesson notes: Mulching covers the surface and can reduce the impact of ____.","choices":["rainfall","particles","field","surface"],"correct":0,"explanation":"Mulching covers the surface and can reduce the impact of rainfall."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('d2b3b162-7b59-4661-a2e2-77444c3881ae','revision:revision-08','grade-8','english','Conversational skills – disagreeing politely · Revision notes','[{"text":"Complete the statement from your lesson notes: Polite disagreement addresses an idea without attacking the other ____.","choices":["speaker","responding","opinion","contradiction"],"correct":0,"explanation":"Polite disagreement addresses an idea without attacking the other speaker."},{"text":"Complete the statement from your lesson notes: Active listening helps a listener understand the claim before ____.","choices":["speaker","responding","opinion","contradiction"],"correct":1,"explanation":"Active listening helps a listener understand the claim before responding."},{"text":"Complete the statement from your lesson notes: A respectful response can acknowledge a useful point before presenting a different ____.","choices":["speaker","responding","opinion","contradiction"],"correct":2,"explanation":"A respectful response can acknowledge a useful point before presenting a different opinion."},{"text":"Complete the statement from your lesson notes: Reasons and examples make a disagreement more helpful than a simple ____.","choices":["speaker","responding","opinion","contradiction"],"correct":3,"explanation":"Reasons and examples make a disagreement more helpful than a simple contradiction."},{"text":"Complete the statement from your lesson notes: Turn-taking gives different speakers a fair opportunity to ____.","choices":["contribute","speaker","responding","opinion"],"correct":0,"explanation":"Turn-taking gives different speakers a fair opportunity to contribute."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('c91bdaad-c7c6-4d57-a468-f51741dfcbb1','revision:revision-09','grade-9','mathematics','Matrices · Revision notes','[{"text":"Complete the statement from your lesson notes: Its order records the number of rows followed by the number of ____.","choices":["columns","order","number","find"],"correct":0,"explanation":"Its order records the number of rows followed by the number of columns."},{"text":"Complete the statement from your lesson notes: Adding matrices requires both matrices to have the same ____.","choices":["columns","order","number","find"],"correct":1,"explanation":"Adding matrices requires both matrices to have the same order."},{"text":"Complete the statement from your lesson notes: Multiplying a matrix by a scalar multiplies each entry by that ____.","choices":["columns","order","number","find"],"correct":2,"explanation":"Multiplying a matrix by a scalar multiplies each entry by that number."},{"text":"Complete the statement from your lesson notes: Create a compatible second matrix and ____ the sum.","choices":["columns","order","number","find"],"correct":3,"explanation":"Create a compatible second matrix and find the sum."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('7f521eda-088e-4fb4-acc2-41560cfbf96e','revision:revision-10','grade-9','general','Nutrition in plants · Revision notes','[{"text":"Complete the statement from your lesson notes: Photosynthesis uses light energy to form organic food from carbon dioxide and ____.","choices":["water","process","tissues","stomata"],"correct":0,"explanation":"Photosynthesis uses light energy to form organic food from carbon dioxide and water."},{"text":"Complete the statement from your lesson notes: Light availability and other environmental conditions can limit the rate of the ____.","choices":["water","process","tissues","stomata"],"correct":1,"explanation":"Light availability and other environmental conditions can limit the rate of the process."},{"text":"Complete the statement from your lesson notes: Water is supplied to the plant through its roots and transport ____.","choices":["water","process","tissues","stomata"],"correct":2,"explanation":"Water is supplied to the plant through its roots and transport tissues."},{"text":"Complete the statement from your lesson notes: Carbon dioxide enters leaves through openings called ____.","choices":["water","process","tissues","stomata"],"correct":3,"explanation":"Carbon dioxide enters leaves through openings called stomata."},{"text":"Complete the statement from your lesson notes: Oxygen is released as a product of ____.","choices":["photosynthesis","water","process","tissues"],"correct":0,"explanation":"Oxygen is released as a product of photosynthesis."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('231217cf-c321-4efc-af4b-afed307c45ed','revision:revision-11','grade-9','agriculture','Integrated Farming · Revision notes','[{"text":"Complete the statement from your lesson notes: Good hygiene is necessary to prevent contamination within the ____.","choices":["system","safe","production","enterprises"],"correct":0,"explanation":"Good hygiene is necessary to prevent contamination within the system."},{"text":"Complete the statement from your lesson notes: Crop residues may become feed or compost when they are suitable and ____.","choices":["system","safe","production","enterprises"],"correct":1,"explanation":"Crop residues may become feed or compost when they are suitable and safe."},{"text":"Complete the statement from your lesson notes: Properly managed livestock manure can contribute nutrients to crop ____.","choices":["system","safe","production","enterprises"],"correct":2,"explanation":"Properly managed livestock manure can contribute nutrients to crop production."},{"text":"Complete the statement from your lesson notes: Crop diversity can spread production risks across different farm ____.","choices":["system","safe","production","enterprises"],"correct":3,"explanation":"Crop diversity can spread production risks across different farm enterprises."},{"text":"Complete the statement from your lesson notes: Resource recycling reduces waste but does not remove the need for careful ____.","choices":["planning","system","safe","production"],"correct":0,"explanation":"Resource recycling reduces waste but does not remove the need for careful planning."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('9f6af0fa-0685-4ebc-ac6a-939d0735364d','revision:revision-12','grade-9','english','Reading for information and meaning · Revision notes','[{"text":"Complete the statement from your lesson notes: Skimming helps a reader gain an overview of the whole ____.","choices":["text","keyword","passage","interpretation"],"correct":0,"explanation":"Skimming helps a reader gain an overview of the whole text."},{"text":"Complete the statement from your lesson notes: Scanning helps a reader locate a particular detail or ____.","choices":["text","keyword","passage","interpretation"],"correct":1,"explanation":"Scanning helps a reader locate a particular detail or keyword."},{"text":"Complete the statement from your lesson notes: Explicit information is stated directly in the written ____.","choices":["text","keyword","passage","interpretation"],"correct":2,"explanation":"Explicit information is stated directly in the written passage."},{"text":"Complete the statement from your lesson notes: An inference combines textual evidence with reasonable ____.","choices":["text","keyword","passage","interpretation"],"correct":3,"explanation":"An inference combines textual evidence with reasonable interpretation."},{"text":"Complete the statement from your lesson notes: Context can help a reader work out an unfamiliar word’s ____.","choices":["meaning","text","keyword","passage"],"correct":0,"explanation":"Context can help a reader work out an unfamiliar word’s meaning."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('50ec4462-2f69-43aa-a87c-b9ae44d69319','revision:revision-13','grade-10','core-mathematics','Indices and Logarithms · Revision notes','[{"text":"Complete the statement from your lesson notes: An index indicates how many factors of a base occur in a positive integer ____.","choices":["power","indices","number","different"],"correct":0,"explanation":"An index indicates how many factors of a base occur in a positive integer power."},{"text":"Complete the statement from your lesson notes: Dividing powers with the same non-zero base involves subtracting their ____.","choices":["power","indices","number","different"],"correct":1,"explanation":"Dividing powers with the same non-zero base involves subtracting their indices."},{"text":"Complete the statement from your lesson notes: A logarithm answers the question of which exponent produces a given positive ____.","choices":["power","indices","number","different"],"correct":2,"explanation":"A logarithm answers the question of which exponent produces a given positive number."},{"text":"Complete the statement from your lesson notes: A real logarithm requires a positive base ____ from one.","choices":["power","indices","number","different"],"correct":3,"explanation":"A real logarithm requires a positive base different from one."},{"text":"Complete the statement from your lesson notes: The argument of a real logarithm must also be ____.","choices":["positive","power","indices","number"],"correct":0,"explanation":"The argument of a real logarithm must also be positive."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('fe2d3183-97d6-4b28-ad14-af250c212968','revision:revision-14','grade-10','biology','Chemicals of life · Revision notes','[{"text":"Complete the statement from your lesson notes: Carbohydrates include simple sugars and larger molecules such as ____.","choices":["starch","acids","proteins","membranes"],"correct":0,"explanation":"Carbohydrates include simple sugars and larger molecules such as starch."},{"text":"Complete the statement from your lesson notes: Proteins are built from smaller units called amino ____.","choices":["starch","acids","proteins","membranes"],"correct":1,"explanation":"Proteins are built from smaller units called amino acids."},{"text":"Complete the statement from your lesson notes: Enzymes are biological catalysts, and most enzymes are ____.","choices":["starch","acids","proteins","membranes"],"correct":2,"explanation":"Enzymes are biological catalysts, and most enzymes are proteins."},{"text":"Complete the statement from your lesson notes: Lipids include substances important in energy storage and cell ____.","choices":["starch","acids","proteins","membranes"],"correct":3,"explanation":"Lipids include substances important in energy storage and cell membranes."},{"text":"Complete the statement from your lesson notes: Nucleic acids contain information used in inheritance and protein ____.","choices":["production","starch","acids","proteins"],"correct":0,"explanation":"Nucleic acids contain information used in inheritance and protein production."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('be961ca0-7a42-434e-a670-6da70f8c2563','revision:revision-15','grade-10','chemistry','The Atom · Revision notes','[{"text":"Complete the statement from your lesson notes: An atom has a small nucleus containing protons and, in most atoms, ____.","choices":["neutrons","tracks","belongs","electrons"],"correct":0,"explanation":"An atom has a small nucleus containing protons and, in most atoms, neutrons."},{"text":"Complete the statement from your lesson notes: Electrons occupy regions outside the nucleus rather than fixed miniature planetary ____.","choices":["neutrons","tracks","belongs","electrons"],"correct":1,"explanation":"Electrons occupy regions outside the nucleus rather than fixed miniature planetary tracks."},{"text":"Complete the statement from your lesson notes: The proton number identifies which chemical element the atom ____ to.","choices":["neutrons","tracks","belongs","electrons"],"correct":2,"explanation":"The proton number identifies which chemical element the atom belongs to."},{"text":"Complete the statement from your lesson notes: An ion forms when an atom or group gains or loses ____.","choices":["neutrons","tracks","belongs","electrons"],"correct":3,"explanation":"An ion forms when an atom or group gains or loses electrons."},{"text":"Complete the statement from your lesson notes: Isotopes of an element have the same proton number but different neutron ____.","choices":["numbers","neutrons","tracks","belongs"],"correct":0,"explanation":"Isotopes of an element have the same proton number but different neutron numbers."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('41f15fc3-9f16-4713-aa93-39d835dd9bec','revision:revision-16','grade-11','core-mathematics','Sequences and Series · Revision notes','[{"text":"Complete the statement from your lesson notes: A sequence is an ordered list of terms following a stated ____.","choices":["rule","sequence","terms","difference"],"correct":0,"explanation":"A sequence is an ordered list of terms following a stated rule."},{"text":"Complete the statement from your lesson notes: Then find the sixth term of a geometric ____ with a = 4 and r = 2.","choices":["rule","sequence","terms","difference"],"correct":1,"explanation":"Then find the sixth term of a geometric sequence with a = 4 and r = 2."},{"text":"Complete the statement from your lesson notes: A geometric sequence has a constant ratio between consecutive ____.","choices":["rule","sequence","terms","difference"],"correct":2,"explanation":"A geometric sequence has a constant ratio between consecutive terms."},{"text":"Complete the statement from your lesson notes: The sequence 3, 7, 11, 15 has first term 3 and common ____ 4.","choices":["rule","sequence","terms","difference"],"correct":3,"explanation":"The sequence 3, 7, 11, 15 has first term 3 and common difference 4."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('45c81d1a-f503-465c-adc0-23ae2b2de3eb','revision:revision-17','grade-11','biology','Ecology · Revision notes','[{"text":"Complete the statement from your lesson notes: A community contains the different populations living in the same ____.","choices":["area","population","present","favourable"],"correct":0,"explanation":"A community contains the different populations living in the same area."},{"text":"Complete the statement from your lesson notes: Births and immigration can increase the size of a ____.","choices":["area","population","present","favourable"],"correct":1,"explanation":"Births and immigration can increase the size of a population."},{"text":"Complete the statement from your lesson notes: Deaths and emigration can reduce the number of individuals ____.","choices":["area","population","present","favourable"],"correct":2,"explanation":"Deaths and emigration can reduce the number of individuals present."},{"text":"Complete the statement from your lesson notes: Limiting factors restrict growth when resources or conditions become less ____.","choices":["area","population","present","favourable"],"correct":3,"explanation":"Limiting factors restrict growth when resources or conditions become less favourable."},{"text":"Complete the statement from your lesson notes: Carrying capacity describes the population an environment can support under particular ____.","choices":["conditions","area","population","present"],"correct":0,"explanation":"Carrying capacity describes the population an environment can support under particular conditions."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('d67eecba-4bd4-49ab-a6b7-8b3a90aa9a35','revision:revision-18','grade-11','chemistry','Reaction Rates · Revision notes','[{"text":"Complete the statement from your lesson notes: Reaction rate measures how quickly reactants are used or products are ____.","choices":["formed","reaction","energy","solution"],"correct":0,"explanation":"Reaction rate measures how quickly reactants are used or products are formed."},{"text":"Complete the statement from your lesson notes: Collisions must involve sufficient energy and appropriate orientation for a ____.","choices":["formed","reaction","energy","solution"],"correct":1,"explanation":"Collisions must involve sufficient energy and appropriate orientation for a reaction."},{"text":"Complete the statement from your lesson notes: A catalyst provides an alternative reaction pathway with lower activation ____.","choices":["formed","reaction","energy","solution"],"correct":2,"explanation":"A catalyst provides an alternative reaction pathway with lower activation energy."},{"text":"Complete the statement from your lesson notes: Greater concentration can increase collision frequency in a suitable reacting ____.","choices":["formed","reaction","energy","solution"],"correct":3,"explanation":"Greater concentration can increase collision frequency in a suitable reacting solution."},{"text":"Complete the statement from your lesson notes: Smaller pieces of a solid expose a larger total surface ____.","choices":["area","formed","reaction","energy"],"correct":0,"explanation":"Smaller pieces of a solid expose a larger total surface area."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('82484b06-45b3-489f-a9aa-1669e5d66d3b','revision:revision-19','grade-12','essential-mathematics','Sets · Revision notes','[{"text":"Complete the statement from your lesson notes: A set is a collection whose membership can be clearly ____.","choices":["determined","problem","sets","once"],"correct":0,"explanation":"A set is a collection whose membership can be clearly determined."},{"text":"Complete the statement from your lesson notes: A universal set defines the objects under consideration in a ____.","choices":["determined","problem","sets","once"],"correct":1,"explanation":"A universal set defines the objects under consideration in a problem."},{"text":"Complete the statement from your lesson notes: The intersection of two sets contains the elements belonging to both ____.","choices":["determined","problem","sets","once"],"correct":2,"explanation":"The intersection of two sets contains the elements belonging to both sets."},{"text":"Complete the statement from your lesson notes: The union contains elements belonging to either set, counting each element ____.","choices":["determined","problem","sets","once"],"correct":3,"explanation":"The union contains elements belonging to either set, counting each element once."},{"text":"Complete the statement from your lesson notes: The complement contains elements in the universal set that are outside the ____ set.","choices":["chosen","determined","problem","sets"],"correct":0,"explanation":"The complement contains elements in the universal set that are outside the chosen set."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('318891e7-01b1-40a4-a83a-e98c1dc56df3','revision:revision-20','grade-12','chemistry','Polymers · Revision notes','[{"text":"Complete the statement from your lesson notes: A polymer is a large molecule containing many repeating structural ____.","choices":["units","monomers","by-product","molecules"],"correct":0,"explanation":"A polymer is a large molecule containing many repeating structural units."},{"text":"Complete the statement from your lesson notes: Smaller starting molecules used to produce polymers are called ____.","choices":["units","monomers","by-product","molecules"],"correct":1,"explanation":"Smaller starting molecules used to produce polymers are called monomers."},{"text":"Complete the statement from your lesson notes: Addition polymerisation can join suitable unsaturated monomers without producing a small-molecule ____.","choices":["units","monomers","by-product","molecules"],"correct":2,"explanation":"Addition polymerisation can join suitable unsaturated monomers without producing a small-molecule by-product."},{"text":"Complete the statement from your lesson notes: Condensation polymerisation links suitable functional groups and releases small ____.","choices":["units","monomers","by-product","molecules"],"correct":3,"explanation":"Condensation polymerisation links suitable functional groups and releases small molecules."},{"text":"Complete the statement from your lesson notes: Chain structure and bonding help explain differences in polymer ____.","choices":["properties","units","monomers","by-product"],"correct":0,"explanation":"Chain structure and bonding help explain differences in polymer properties."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('bcb07636-20d5-4f7b-a227-7c2c364666f3','revision:revision-21','grade-12','physics','Electromagnetic induction · Revision notes','[{"text":"Complete the statement from your lesson notes: Electromagnetic induction can produce an electromotive force when magnetic flux linkage ____.","choices":["changes","coil","force","conditions"],"correct":0,"explanation":"Electromagnetic induction can produce an electromotive force when magnetic flux linkage changes."},{"text":"Complete the statement from your lesson notes: Moving a magnet relative to a coil can change the flux through the ____.","choices":["changes","coil","force","conditions"],"correct":1,"explanation":"Moving a magnet relative to a coil can change the flux through the coil."},{"text":"Complete the statement from your lesson notes: A stationary arrangement with constant flux does not maintain an induced electromotive ____.","choices":["changes","coil","force","conditions"],"correct":2,"explanation":"A stationary arrangement with constant flux does not maintain an induced electromotive force."},{"text":"Complete the statement from your lesson notes: A greater number of turns can increase the effect under comparable ____.","choices":["changes","coil","force","conditions"],"correct":3,"explanation":"A greater number of turns can increase the effect under comparable conditions."},{"text":"Complete the statement from your lesson notes: The direction of induced current opposes the change producing it, according to ____’s law.","choices":["Lenz","changes","coil","force"],"correct":0,"explanation":"The direction of induced current opposes the change producing it, according to Lenz’s law."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('571ca267-c8fc-4977-a902-0ca1fc8cee58','revision:revision-22','form-3','mathematics','Quadratic Expressions and Equations II · Revision notes','[{"text":"Complete the statement from your lesson notes: A quadratic equation can be written as ax² + bx + c = 0 with a non-zero ____ a.","choices":["coefficient","exist","zero","roots"],"correct":0,"explanation":"A quadratic equation can be written as ax² + bx + c = 0 with a non-zero coefficient a."},{"text":"Complete the statement from your lesson notes: Factoring expresses a quadratic as a product when suitable factors ____.","choices":["coefficient","exist","zero","roots"],"correct":1,"explanation":"Factoring expresses a quadratic as a product when suitable factors exist."},{"text":"Complete the statement from your lesson notes: The zero-product rule states that a product is zero only if at least one factor is ____.","choices":["coefficient","exist","zero","roots"],"correct":2,"explanation":"The zero-product rule states that a product is zero only if at least one factor is zero."},{"text":"Complete the statement from your lesson notes: Solve 2x² − 7x + 3 = 0 by factorisation and verify both ____.","choices":["coefficient","exist","zero","roots"],"correct":3,"explanation":"Solve 2x² − 7x + 3 = 0 by factorisation and verify both roots."},{"text":"Complete the statement from your lesson notes: Substitution into the original equation provides a useful final ____.","choices":["check","coefficient","exist","zero"],"correct":0,"explanation":"Substitution into the original equation provides a useful final check."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('26c2ccdc-fc32-4552-a021-789c1347ce07','revision:revision-23','form-3','biology','Ecology · Revision notes','[{"text":"Complete the statement from your lesson notes: An ecosystem includes living organisms and the physical conditions surrounding ____.","choices":["them","sunlight","organisms","environment"],"correct":0,"explanation":"An ecosystem includes living organisms and the physical conditions surrounding them."},{"text":"Complete the statement from your lesson notes: Producers build organic food using an energy source such as ____.","choices":["them","sunlight","organisms","environment"],"correct":1,"explanation":"Producers build organic food using an energy source such as sunlight."},{"text":"Complete the statement from your lesson notes: Consumers obtain organic food by feeding on other ____.","choices":["them","sunlight","organisms","environment"],"correct":2,"explanation":"Consumers obtain organic food by feeding on other organisms."},{"text":"Complete the statement from your lesson notes: Decomposers help break down dead organic matter and return nutrients to the ____.","choices":["them","sunlight","organisms","environment"],"correct":3,"explanation":"Decomposers help break down dead organic matter and return nutrients to the environment."},{"text":"Complete the statement from your lesson notes: Food-chain arrows indicate the direction of energy transfer from food to ____.","choices":["consumer","them","sunlight","organisms"],"correct":0,"explanation":"Food-chain arrows indicate the direction of energy transfer from food to consumer."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
INSERT INTO subject_question_sets(id,source_key,class_level,subject,title,questions,created_at) VALUES('cf417373-e90f-460f-a364-c6e91f9a7a82','revision:revision-24','form-3','physics','Linear Motion · Revision notes','[{"text":"Complete the statement from your lesson notes: Distance is the total length of the path travelled by an ____.","choices":["object","direction","time","interval"],"correct":0,"explanation":"Distance is the total length of the path travelled by an object."},{"text":"Complete the statement from your lesson notes: Displacement measures the change of position with a specified ____.","choices":["object","direction","time","interval"],"correct":1,"explanation":"Displacement measures the change of position with a specified direction."},{"text":"Complete the statement from your lesson notes: Acceleration measures the change in velocity per unit ____.","choices":["object","direction","time","interval"],"correct":2,"explanation":"Acceleration measures the change in velocity per unit time."},{"text":"Complete the statement from your lesson notes: Average velocity uses displacement divided by the same time ____.","choices":["object","direction","time","interval"],"correct":3,"explanation":"Average velocity uses displacement divided by the same time interval."},{"text":"Complete the statement from your lesson notes: Uniform acceleration allows the use of equations ____ as v = u + at.","choices":["such","object","direction","time"],"correct":0,"explanation":"Uniform acceleration allows the use of equations such as v = u + at."}]',1793491200000) ON CONFLICT(source_key,class_level) DO NOTHING;
